        "code": "// If the browser doesn't have fetch natively...\nif (!window.fetch) {\n    // A polyfill library injects its own version of fetch\n    // that secretly uses the old XMLHttpRequest under the hood!\n    window.fetch = function(url, options) {\n        return new Promise((resolve, reject) => {\n            const xhr = new XMLHttpRequest();\n            // ... polyfill logic ...\n        });\n    };\n}",
