        "id": 167,
        "title": "How do you implement retry logic for failed AJAX requests?",
        "category": "Bonus: Advanced AJAX & Edge Cases",
        "language": "javascript",
        "explanation": "Networks are unreliable. A request might fail simply because the user drove through a tunnel. \nRobust applications implement a retry mechanism (usually with 'exponential backoff') to automatically attempt the AJAX call a few more times before finally showing an error.",
        "example": "Recursive retry logic.",
        "code": "function fetchWithRetry(url, retries = 3) {\n    $.ajax({\n        url: url,\n        success: function(data) { console.log(\"Success!\"); },\n        error: function(jqXHR) {\n            // Only retry on network errors or 5xx server errors, not 4xx client errors\n            if (retries > 0 && (jqXHR.status >= 500 || jqXHR.status === 0)) {\n                console.log(\"Failed. Retrying... \" + retries + \" attempts left.\");\n                // Wait 1 second before retrying\n                setTimeout(() => fetchWithRetry(url, retries - 1), 1000);\n            } else {\n                console.log(\"Final Failure.\");\n            }\n        }\n    });\n}",
