        "code": "async function loadDashboard() {\n    try {\n        // Fire both requests simultaneously\n        const userPromise = $.get('/api/user');\n        const statsPromise = $.get('/api/stats');\n        \n        // Wait for both to finish. \n        // Destructure the results array directly.\n        const [userData, statsData] = await Promise.all([userPromise, statsPromise]);\n        \n        console.log(\"Both finished!\", userData, statsData);\n    } catch (error) {\n        // If EITHER request fails, execution drops to here\n        console.error(\"Dashboard failed to load\", error);\n    }\n}",
